package io.questdb.maven.rust;

import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugin.MojoFailureException;
import org.apache.maven.plugins.annotations.LifecyclePhase;
import org.apache.maven.plugins.annotations.Mojo;
import org.apache.maven.plugins.annotations.Parameter;

@Mojo(name = "test", defaultPhase = LifecyclePhase.TEST, threadSafe = true)
public class CargoTestMojo extends CargoMojoBase {
 /**
 * Skips running tests when building with `mvn package -DskipTests=true`.
 */
 @Parameter(property = "skipTests", defaultValue = "false")
 private boolean skipTests;

 /**
 * Use cross-rs to build a cross-compiled binary.
 */
 @Parameter(property = "cross", defaultValue = "false")
 private boolean cross;

 /**
 * Use xwin to build a cross-compiled binary.
 */
 @Parameter(property = "xWin", defaultValue = "false")
 private boolean xWin;

 @Override
 public void execute() throws MojoExecutionException, MojoFailureException {
 if (skip || skipTests) {
 getLog().info("Skipping tests");
 return;
 }
 final Crate crate = new Crate(
 getCrateRoot(),
 getTargetRootDir(),
 getCommonCrateParams());
 crate.setLog(getLog());
 crate.test(getToolchain());
 }

 private String getToolchain() {
 if (cross) {
 return "cross";
 }
 if (xWin) {
 return "xwin";
 }
 return null;
 }
}
